`timescale 1ns/1ps
// Auto-generated by autombist from config.yml: a BEHAVIORAL model of the memory,
// writes on the rising edge, reads one clock after the registered access, data held until the next read, a read of an address another port writes in the same cycle X (read_latency 1).
// Idealized: fault-free, no timing checks, contents power up unknown. It is NOT the
// macro's own model; pass that model to run_tb.sh to replace this one.
// Column-muxed, 2 words per row: each spare lane is one cell per physical
// row, shared by the row's words and kept at its first address (OpenRAM's layout).
module sram_s2d1r1wmux #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 8,
    parameter integer NUM_SPARE_ROWS = 1,
    parameter integer NUM_SPARE_COLS = 1
) (
    input  wire clk0,
    input  wire csb0,
    input  wire [4:0] addr0,
    output reg  [8:0] dout0,
    input  wire clk1,
    input  wire csb1,
    input  wire web1,
    input  wire [4:0] addr1,
    input  wire [8:0] din1,
    input  wire [0:0] spare_wen1
);
    // The wrapper overrides the parameters above; the widths below are the ones it connects.
    localparam integer LOGICAL_W = 8;
    localparam integer DEPTH = 32;
    reg [8:0] mem [0:DEPTH-1];

    // The word at a: its logical bits from mem[a], its spare lanes from the row's
    // first address, the one spare cell its physical row has.
    function [8:0] word_at(input [4:0] a);
        reg [4:0] b;
        reg [8:0] w, s;
        begin
            b = {a[4:1], 1'b0};
            w = mem[a];
            s = mem[b];
            word_at = {s[8:LOGICAL_W], w[LOGICAL_W-1:0]};
        end
    endfunction

    // port 0: r
    reg p0_csb_q;
    reg [4:0] p0_addr_q;
    always @(posedge clk0) begin
        p0_csb_q  <= csb0;
        p0_addr_q <= addr0;
        if (!p0_csb_q && 1'b1) dout0 <= p0_read(p0_addr_q);
    end

    // port 1: w
    reg p1_csb_q;
    reg [4:0] p1_addr_q;
    reg p1_we_q;
    reg [0:0] p1_spare_q;
    integer p1_k;
    always @(posedge clk1) begin
        p1_csb_q  <= csb1;
        p1_addr_q <= addr1;
        p1_we_q   <= web1;
        p1_spare_q <= spare_wen1[0:0];
        if (!csb1 && !web1) begin
            mem[addr1][LOGICAL_W-1:0] <= din1[LOGICAL_W-1:0];
            for (p1_k = 0; p1_k < 1; p1_k = p1_k + 1)
                if (spare_wen1[p1_k]) mem[{addr1[4:1], 1'b0}][LOGICAL_W + p1_k] <= din1[LOGICAL_W + p1_k];
        end
    end

    // port 0's read: X if another port wrote the same address in the same cycle
    function [8:0] p0_read(input [4:0] a);
        integer k;
        begin
            p0_read = word_at(a);
            if (!p1_csb_q && !p1_we_q && p1_addr_q[4:1] == a[4:1])
                for (k = 0; k < 1; k = k + 1)
                    if (p1_spare_q[k]) p0_read[LOGICAL_W + k] = 1'bx;
            if (!p1_csb_q && !p1_we_q && p1_addr_q == a) p0_read = {9{1'bx}};
        end
    endfunction

endmodule
